func checkDefaultArguments() async throws {
    _ = greet(name: "Ada")
    _ = greet(name: "Ada", shout: false, suffix: "!")
    _ = Server().port()
    _ = try await Server.start(port: 8080).port(mapped: true)
    _ = formatDefaults(name: "Ada")
    _ = formatDefaults(name: "Ada", enabled: false, weight: nil)
    _ = try await asyncDefault()
    _ = applyOptionalClosure(value: 21)
    _ = applyOptionalClosure(value: 21, callback: nil)
    _ = applyOptionalClosure(value: 21, callback: { value in value * 2 })

    let counter = DefaultCounter()
    _ = DefaultCounter.fromText()
    _ = DefaultCounter.fromText(value: "12")
    _ = DefaultCounter(offset: 3)
    _ = counter.offset()
    _ = DefaultCounter.sum(right: 5)
    _ = try await counter.asyncOffset()

    let amount = DefaultAmount()
    _ = DefaultAmount.withScaledValue()
    _ = DefaultAmount.tryScaledValue()
    _ = DefaultAmount(value: 9)
    _ = amount.offset()
    _ = NamedAmount()
    _ = NamedAmount.empty()
    _ = NamedAmount(withValue: 9)
    _ = DefaultMode.quiet.matches()
    _ = DefaultMode()
    _ = DefaultMode.withMode()
    _ = try await DefaultMode.load()
    _ = try await NamedAmount.load()

    _ = span()
    _ = throttle()
    _ = defaultAmount()
    _ = FloatDefaults()
    _ = defaultFloatBits()
    _ = defaultDoubleBits()
    _ = ContactDefaults()
    _ = defaultEmail()
    _ = defaultIdentifier()
    _ = defaultOptionalEmail()
}
